_A08_C1.jpg","image_paths":["demo/stride-colors-20261109/stride_color_20261109_A08_C1.jpg"],"image_source":"catalog_reference","image_color":"Đen","local_source":"assets/images/stride_color_20261109_A08_C1.jpg","bucket":"product-images"},{"key":"A08","category":"apparel","color_index":2,"color":"Xám","sizes":["S","M","L","XL","XXL"],"image_path":"demo/stride-colors-20261109/stride_color_20261109_A08_C2.png","image_paths":["demo/stride-colors-20261109/stride_color_20261109_A08_C2.png"],"image_source":"ai_color_preview","image_color":"Xám","local_source":"assets/images/stride_color_20261109_A08_C2.png","bucket":"product-images"},{"key":"A08","category":"apparel","color_index":3,"color":"Trắng","sizes":["S","M","L","XL","XXL"],"image_path":"demo/stride-colors-20261109/stride_color_20261109_A08_C3.png","image_paths":["demo/stride-colors-20261109/stride_color_20261109_A08_C3.png"],"image_source":"ai_color_preview","image_color":"Trắng","local_source":"assets/images/stride_color_20261109_A08_C3.png","bucket":"product-images"},{"key":"A08","category":"apparel","color_index":4,"color":"Xanh ngọc","sizes":["S","M","L","XL","XXL"],"image_path":"demo/stride-colors-20261109/stride_color_20261109_A08_C4.png","image_paths":["demo/stride-colors-20261109/stride_color_20261109_A08_C4.png"],"image_source":"ai_color_preview","image_color":"Xanh ngọc","local_source":"assets/images/stride_color_20261109_A08_C4.png","bucket":"product-images"}]$dataset$::jsonb;
  item jsonb;
  category uuid;
  product uuid;
  product_count int;
  variant public.product_variants%rowtype;
  size_label text;
  variant_sku text;
  target_attributes jsonb;
  image_attributes jsonb;
  expected_image_path text;
  expected_image_source text;
  seen_skus text[] := array[]::text[];
  matched_count int := 0;
  old_note constant text := 'Ảnh minh họa; ảnh có thể không thể hiện tất cả màu của biến thể.';
  new_note constant text := 'Ảnh màu dùng để minh họa dữ liệu demo; ảnh được tạo bằng AI có ghi chú riêng.';
begin
  -- Fail before ANY catalog update if the real upload is incomplete or public.
  if not exists (select 1 from storage.buckets b where b.id='product-images' and not b.public) then
    raise exception 'Expected private product-images Storage bucket';
  end if;
  if jsonb_array_length(image_manifest)<>52 then
    raise exception 'Expected 52 STRIDE Storage images in manifest';
  end if;
  for item in select value from jsonb_array_elements(image_manifest)
  loop
    if not exists (select 1 from storage.objects o
      where o.bucket_id='product-images' and o.name=item->>'image_path') then
      raise exception 'Missing uploaded STRIDE Storage image: %',item->>'image_path';
    end if;
  end loop;
  for item in select value from jsonb_array_elements(image_manifest)
  loop
    select id into strict category from public.categories
      where code=item->>'category' and is_active;
    select count(distinct v.product_id),min(v.product_id::text)::uuid
      into product_count,product from public.product_variants v
      where v.sku like 'DEMO-STRIDE-20261108-' || (item->>'key') || '-%';
    if product_count<>1 or not exists (
      select 1 from public.products p where p.id=product and p.category_id=category
        and p.description like '[DEMO STRIDE 20261108]%'
    ) then
      raise exception 'Missing/colliding STRIDE image product for %',item->>'key';
    end if;
    expected_image_path:='demo/stride-colors-20261109/stride_color_20261109_' || (item->>'key') ||
      '_C' || (item->>'color_index') || case
        when (item->>'color_index')::int<>1 or item->>'key'='S02' then '.png'
        when item->>'category'='shoes' then '.webp' else '.jpg' end;
    expected_image_source:=case when (item->>'color_index')::int=1 and item->>'key'<>'S02' then 'catalog_reference' else 'ai_color_preview' end;
    if (item->>'bucket') is distinct from 'product-images'
      or (item->>'color_index')::int not between 1 and 4
      or item->>'image_path' is distinct from expected_image_path
      or item->'image_paths' is distinct from jsonb_build_array(item->>'image_path')
      or item->>'image_color' is distinct from item->>'color'
      or item->>'image_source' is distinct from expected_image_source
    then
      raise exception 'Invalid STRIDE image manifest for %',item->>'key';
    end if;
    image_attributes:=jsonb_build_object(
      'image_path',item->>'image_path','image_paths',item->'image_paths',
      'image_source',item->>'image_source','image_color',item->>'image_color');
    for size_label in select value from jsonb_array_elements_text(item->'sizes')
    loop
      variant_sku:='DEMO-STRIDE-20261108-' || (item->>'key') || '-C' || (item->>'color_index') || '-' || size_label;
      if variant_sku=any(seen_skus) then
        raise exception 'Duplicate STRIDE image SKU in manifest: %',variant_sku;
      end if;
      seen_skus:=array_append(seen_skus,variant_sku);
      select * into variant from public.product_variants where sku=variant_sku for update;
      if not found then
        raise exception 'Missing STRIDE image variant: %',variant_sku;
      end if;
      if variant.product_id<>product
        or variant.attributes->>'color' is distinct from item->>'color'
        or variant.attributes->>'size' is distinct from size_label
        or variant.attributes->'demo' is distinct from 'true'::jsonb then
        raise exception 'STRIDE image variant ownership/color/size collision: %',variant_sku;
      end if;
      target_attributes:=variant.attributes || image_attributes;
      if variant.attributes is distinct from target_attributes then
        update public.product_variants set attributes=target_attributes where id=variant.id;
      end if;
      matched_count:=matched_count+1;
    end loop;
    -- Replace only the exact old seed sentence; retain merchant custom text.
    update public.products p set description=replace(p.description,old_note,new_note)
      where p.id=product and position(old_note in p.description)>0;
  end loop;
  if matched_count<>340 then
    raise exception 'Expected 340 existing STRIDE image variants, found %',matched_count;
  end if;
end;
$seed$;
commit;
